import React, { useEffect, useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min";
import { useNavigate } from "react-router-dom";
import Popup from "./Popup";
import Button from "react-bootstrap/Button";
import axios from "axios";
import { Group } from "../Model/Group.model";
import AddIcon from "@mui/icons-material/Add";
import "./groups.scss";

function Groups() {
  const navigate = useNavigate();
  const [groups, setGroups] = useState<Group[]>([]);
  const [showPopup, setShowPopup] = useState<boolean>(false);

  useEffect(() => {
    axios
      .get<Group[]>(`http://localhost:5257/api/Group/`)
      .then((response) => {
        setGroups(response.data);
        console.log(response.data);
      })
      .catch((error) => {
        console.log(error);
      });
  }, []);

  const openGroup = (event: any, groupId: string) => {
    event?.stopPropagation();
    navigate(`/group/${groupId}`);
  };
  const handleOpenPopup = () => {
    setShowPopup(true);
  };

  const handleClosePopup = () => {
    setShowPopup(false);
  };

  const onCreate = (value: string) => {
    axios
      .post<Group>("http://localhost:5257/api/Group", { name: value })
      .then((response) => {
        setGroups((old) => [...old, response.data]);
      })
      .catch((error) => {
        alert("Name cannot be empty");
      });
  };

  const checkHandler = (idToUpdate: string, checked: boolean) => {
    const group = groups.find((x) => x.id === idToUpdate);
    if (group != null) {
      setGroups((group) =>
        group.map((x) =>
          x.id === idToUpdate ? { ...x, isChecked: !checked } : x
        )
      );
    }
  };
  return (
    <div className="table-responsive container-md p-4 border border rounded-4 bg-body-tertiary mt-5 shadow p-3 mb-5 bg-body-tertiary rounded">
      <button onClick={handleOpenPopup} className="btn mb-3 float-end" id="group-button">
        <AddIcon fontSize="small" />
        <span className="p-2">Add New Group</span>
      </button>

      <Popup
        show={showPopup}
        onClose={handleClosePopup}
        title="Enter new group name"
        onSubmit={(name) => onCreate(name)}
      />
      <h2 className="fw-bold float-start">Groups</h2>
      <table className="rounded-3 overflow-hidden table table-responsive table-hover table-borderless table-primary align-middle">
        <thead className="table-success">
          <tr>
            <th></th>
            <th className="fw-semibold">NAME</th>
            <th className="fw-semibold">MEMBERS</th>
            <th className="fw-semibold ">YOU OWE</th>
            <th className="fw-semibold ">OWES YOU</th>
            <th className="fw-semibold ">CREATED</th>
            <th className="fw-semibold ">ACTIONS</th>
          </tr>
        </thead>
        <tbody>
          {groups.map((group) => (
            <tr
              key={group.name}
              className="table-secondary"
              onClick={() => checkHandler(group.id, group.isChecked)}
            >
              <td>
                <input
                  className="form-check-input"
                  type="checkbox"
                  id={group.id}
                  checked={group.isChecked}
                />
              </td>
              <td className="">{group.name}</td>
              <td>{group.totalOwe.toFixed(2)} $</td>
              <td>{group.totalOwed.toFixed(2)} $</td>
              <td></td>
              <td></td>
              <td>
                <a href={group.id} onClick={(e) => openGroup(e, group.id)}>
                  View
                </a>
              </td>
            </tr>
          ))}
        </tbody>
        <tfoot></tfoot>
      </table>
    </div>
  );
}

export default Groups;
